/bin/bash -lc "python3 - <<'PY'
from html.parser import HTMLParser
from urllib.request import Request, urlopen

class Paragraphs(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_paragraph = False
        self.paragraphs = []
    def handle_starttag(self, tag, attrs):
        if tag == 'p':
            self.in_paragraph = True
            self.paragraphs.append('')
    def handle_endtag(self, tag):
        if tag == 'p':
            self.in_paragraph = False
    def handle_data(self, data):
        if self.in_paragraph:
            self.paragraphs[-1] += data

for label, headers in [
    ('provided preferences', {'Cookie': 'theme=dark', 'Accept-Language': 'fr-CA,fr;q=0.9,en;q=0.8'}),
    ('default theme', {'Accept-Language': 'en-US,en;q=0.9'}),
]:
    response = urlopen(Request('http://localhost:3100/', headers=headers))
    parser = Paragraphs()
    parser.feed(response.read().decode())
    print(label, parser.paragraphs)
PY"
